-- MCR's legacy tax, MATCHED to QuickBooks and never recomputed.
--
-- STRATA holds 3,759 imported QuickBooks invoices and not one carries tax, while
-- the QuickBooks books show $59,749.51 of General Excise Tax across seven years.
-- Every imported invoice in STRATA is therefore short by whatever GET the
-- customer was actually charged. This restores it for the orders STRATA holds:
-- 3,793 orders, $11,473.11.
--
-- ── WHY MATCHED, NOT RECOMPUTED ──────────────────────────────────────────────
-- Recomputing looks tempting and is wrong by $11,530.51. Verified independently
-- against the 18,629 source documents:
--
--   tax MCR actually charged        $59,749.51
--   tax a full recompute produces   $71,280.02
--   invented out of nothing         $11,530.51
--
-- A rate cannot express a decision. 805 documents carry a taxable rate label and
-- $0.00 of tax on $1,688,236.10 of sales — overwhelmingly Costco Wholesale at
-- $1.79M. Passing GET on is optional and capped in Hawaii, and MCR chose not to
-- on those. Recomputing would invent GET they never charged and never remitted,
-- and would put it on invoices the customer already paid.
--
-- So each order takes the tax QuickBooks printed on it. To the cent, by
-- construction.
--
-- ── ORDER OF OPERATIONS ──────────────────────────────────────────────────────
-- This must run BEFORE any legacy invoice is posted: guard_posted_order_immutable
-- locks tax_amount and tax_rate on posted rows. Only 2 of MCR's orders are posted
-- and neither is a QuickBooks import, so the window is open — and step 0 asserts
-- that rather than trusting it.
--
-- ── THIS MOVES REAL MONEY ON REAL SCREENS ────────────────────────────────────
-- tax_amount already has consumers that compute order_total + tax_amount
-- (invoice_ar_balances, lib/ar/invoiceRegister.ts, the order detail page,
-- lib/shop/invoiceDispatch.ts). MCR's A/R rises by $11,473.11 when this commits.
-- That IS the correction — it makes STRATA agree with the invoice the customer is
-- holding — but it is an accounting event, not a quiet one.
--
-- ── THE BANDS ────────────────────────────────────────────────────────────────
-- Rates as MCR's own books charge them, verified across seven years. The
-- asymmetry is real and is not a typo: retail is grossed up (4% -> 4.1666667%,
-- matching 296 of 355 taxed retail invoices to the cent) and wholesale is FLAT
-- 0.5% (matching 16,752 of 17,026, where the grossed-up 0.50251% matches only
-- 4,793). See 20260827000002 for why a band stores the statutory rate and derives
-- the charge rate.
--
-- 218 orders get tax with NO band: 145 are the untaxed-by-choice cases carrying
-- $0.00, and 73 carry $110.75 between them with a label this extract could not
-- resolve. Their AMOUNT still matches QuickBooks, which is what the customer's
-- invoice says; the band is left NULL rather than guessed, because NULL means
-- unresolved and a guessed band would file wrongly.

begin;

-- 0. Refuse to run if any target is posted. A posted invoice is immutable and
--    this would raise mid-flight; better to fail on the assertion with a clear
--    message than half-apply.
do $$
declare n int;
begin
  select count(*) into n from public.orders
   where company_id='9ShiyDAXhV' and coalesce(posted,false) and qb_txn_id is not null;
  if n > 0 then
    raise exception 'ABORT: % legacy QuickBooks orders are already posted; their tax is locked', n;
  end if;
end $$;

-- 1. MCR's three Hawaii bands.
insert into public.tax_rate
  (tax_rate_id, company_id, jurisdiction_id, code, label, statutory_rate, gross_up, kind, requires_exemption_doc, filing_class)
select v.id, '9ShiyDAXhV', j.jurisdiction_id, v.code, v.label, v.rate, v.gross, v.kind, v.doc, v.filing
from (values
    ('mcr-hi-wholesale','GET_WHOLESALE','GET wholesale 0.5%',      0.005, false, 'reduced',  true,  'wholesaling'),
    ('mcr-hi-retail',   'GET_RETAIL',   'GET retail 4% (at 4.1667%)', 0.04, true,  'standard', false, 'retailing'),
    ('mcr-hi-exempt',   'GET_EXEMPT',   'Exempt / not subject',        0.0, false, 'exempt',   false, 'exempt')
  ) as v(id, code, label, rate, gross, kind, doc, filing)
cross join lateral (
    -- 20260827000002 seeds this deterministically as 'us-hi'. Matched by id
    -- rather than by subdivision, because the seeded code is 'US-HI' and an
    -- earlier draft here looked for 'HI', matched nothing, and silently created
    -- no bands at all — the backfill then failed on the foreign key rather than
    -- quietly writing tax with no band, which is the one mercy in that mistake.
    select jurisdiction_id from public.tax_jurisdiction
     where jurisdiction_id = 'us-hi' limit 1
  ) j
on conflict (tax_rate_id) do nothing;

-- 2. The tax each order actually carried, straight off its QuickBooks invoice.
create temporary table _qb_tax(
  order_id     text primary key,
  qb_txn_id    text,
  tax_amount   numeric,
  tax_rate     numeric,
  tax_rate_id  text,
  qb_pretax    numeric,
  bucket       text
) on commit drop;

