    ('mcrimp-ord-fed6616baec2947a','CM RGS 2026',0.00,0.0,'mcr-hi-exempt',-338.28,'exempt_coded'),
    ('mcrimp-ord-c66f561899630d1f','CM SWF 2026',0.00,0.0,'mcr-hi-exempt',-389.68,'exempt_coded'),
    ('mcrimp-ord-4fb15765a0cea37d','CM IGD 2026',0.00,0.0,'mcr-hi-exempt',-747.87,'exempt_coded');

update public.orders o
   set tax_amount  = q.tax_amount,
       tax_rate    = q.tax_rate,
       tax_rate_id = q.tax_rate_id
  from _qb_tax q
 where o.order_id = q.order_id
   and o.company_id = '9ShiyDAXhV';

-- 3. Prove it landed and that STRATA's pre-tax total still agrees with
--    QuickBooks' pre-tax subtotal. If these disagree the tax is being attached to
--    a different number than the one it was computed from.
do $$
declare n_tax int; v_tax numeric; n_drift int;
begin
  select count(*) filter (where o.tax_amount is not null), coalesce(sum(o.tax_amount),0)
    into n_tax, v_tax
    from public.orders o join _qb_tax q using(order_id);

  select count(*) into n_drift
    from public.orders o join _qb_tax q using(order_id)
   where abs(coalesce(o.order_total,0) - q.qb_pretax) > 0.02;

  raise notice 'tax applied to % orders, $%', n_tax, round(v_tax,2);
  raise notice 'orders whose pre-tax total disagrees with QuickBooks: %', n_drift;
end $$;

commit;
